import{_ as r,C as a,o as c,c as t,ag as i,E as s}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"ドキュメント","description":"","frontmatter":{},"headers":[],"relativePath":"ja/docs/index.md","filePath":"ja/docs/index.md"}'),d={name:"ja/docs/index.md"};function n(l,e,m,f,u,_){const o=a("StatusNote");return c(),t("div",null,[e[0]||(e[0]=i('<h1 id="ドキュメント" tabindex="-1">ドキュメント <a class="header-anchor" href="#ドキュメント" aria-label="Permalink to &quot;ドキュメント&quot;">​</a></h1><p>現在の official Form corpus は <code>edge.forms.takoform.com</code> 一つだけです。exact な Experimental <code>0.x</code> Form 16個、Interface 7個、Binding 6個を <a href="https://github.com/tako0614/takoform-forms/tree/3a395e4d7f9f652a942da52905857fccc41b467e" target="_blank" rel="noreferrer"><code>takoform-forms</code> commit <code>3a395e4</code>（英語のみ）</a> で固定しています。</p><h2 id="現在の-normative-contract" tabindex="-1">現在の normative contract <a class="header-anchor" href="#現在の-normative-contract" aria-label="Permalink to &quot;現在の normative contract&quot;">​</a></h2><p>現在の導線は番号付き Specification receipt ではなく、Host API v1 と Form/Core contract です（以下の詳細ページは <strong>英語のみ</strong>）。</p><ul><li><a href="/spec/host-api/v1.html">Host API v1（英語のみ）</a></li><li><a href="/spec/form-definition/">Form Definition（英語のみ）</a></li><li><a href="/spec/form-package/">Form Package（英語のみ）</a></li><li><a href="/spec/interface-contract/">Interface contracts（英語のみ）</a></li><li><a href="/spec/binding-contract/">Binding contracts（英語のみ）</a></li><li><a href="/spec/core/">Core contracts（英語のみ）</a></li></ul><p>Specification 1.0/1.1 receipt は履歴 archive です。API v1.1 や新しい Form / Provider release の current lane ではありません。</p><h2 id="provider-boundary-と-version-stream" tabindex="-1">Provider boundary と version stream <a class="header-anchor" href="#provider-boundary-と-version-stream" aria-label="Permalink to &quot;Provider boundary と version stream&quot;">​</a></h2><p>Takoform には Host API、各 Form definition、Core/library software、Provider software の4つの独立した version stream があります。Form Package API identifier <code>packages.forms.takoform.com/v1alpha5</code> は data wire/envelope format であり、product の 5つ目の version 軸ではありません。</p><p>canonical Registry Provider は official-Forms-only の typed tool です。第三者 Form package は同じ Host API path と package/verification contract を使い、自分の namespace で明示的な Provider mapping を公開します。generic carrier や universal infrastructure provider ではありません。一つの Terraform / OpenTofu module で official Takoform Provider と他の Takoform / industry-standard Provider を組み合わせられます。</p><p>Provider <code>3.0.0</code> は公開済み実装ですが、8 family / 31 resource の不変 projection は Provider release の履歴であり current publisher corpus ではありません。Edge16 の official-only mapping は次 major candidate（未公開）です。<code>&gt;=3.1.0</code> の例も candidate / unpublished として release record で確認されるまで install を主張しません。</p><h2 id="current-edge-family-16-forms" tabindex="-1">Current Edge family（16 Forms） <a class="header-anchor" href="#current-edge-family-16-forms" aria-label="Permalink to &quot;Current Edge family（16 Forms）&quot;">​</a></h2><p>worker は identity、bundle、version、deployment、attachment の不変 resource chain で 構成します。各 resource の詳細は <strong>英語のみ</strong> です。</p><ul><li><a href="/docs/resources/module_worker.html"><code>takoform_module_worker</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_bundle.html"><code>takoform_worker_bundle</code>（英語のみ）</a></li><li><a href="/docs/resources/static_asset_bundle.html"><code>takoform_static_asset_bundle</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_version.html"><code>takoform_worker_version</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_deployment.html"><code>takoform_worker_deployment</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_custom_domain.html"><code>takoform_worker_custom_domain</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_endpoint.html"><code>takoform_worker_endpoint</code>（英語のみ）</a></li><li><a href="/docs/resources/worker_cron_trigger.html"><code>takoform_worker_cron_trigger</code>（英語のみ）</a></li><li><a href="/docs/resources/edge_kv_namespace.html"><code>takoform_edge_kv_namespace</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_database.html"><code>takoform_sqlite_database</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_migration_set.html"><code>takoform_sqlite_migration_set</code>（英語のみ）</a></li><li><a href="/docs/resources/sqlite_migration_application.html"><code>takoform_sqlite_migration_application</code>（英語のみ）</a></li><li><a href="/docs/resources/at_least_once_queue.html"><code>takoform_at_least_once_queue</code>（英語のみ）</a></li><li><a href="/docs/resources/queue_consumer.html"><code>takoform_queue_consumer</code>（英語のみ）</a></li><li><a href="/docs/resources/durable_workflow.html"><code>takoform_durable_workflow</code>（英語のみ）</a></li><li><a href="/docs/resources/actor_namespace.html"><code>takoform_actor_namespace</code>（英語のみ）</a></li></ul><h2 id="非-edge-candidate-履歴・保留、英語のみ" tabindex="-1">非 Edge candidate（履歴・保留、英語のみ） <a class="header-anchor" href="#非-edge-candidate-履歴・保留、英語のみ" aria-label="Permalink to &quot;非 Edge candidate（履歴・保留、英語のみ）&quot;">​</a></h2><p>Function、Container、Table、Pull Queue、Topic、Schedule、Vector の Form は現在の official corpus ではありません。旧 Provider projection の履歴 source を保持し、Current navigation から外しています。</p><ul><li>Function: <a href="/docs/resources/function.html"><code>takoform_function</code>（英語のみ・保留）</a>、<a href="/docs/resources/function_version.html"><code>takoform_function_version</code>（英語のみ・保留）</a>、<a href="/docs/resources/function_deployment.html"><code>takoform_function_deployment</code>（英語のみ・保留）</a>、<a href="/docs/resources/function_endpoint.html"><code>takoform_function_endpoint</code>（英語のみ・保留）</a></li><li>Container: <a href="/docs/resources/serverless_container_service.html"><code>takoform_serverless_container_service</code>（英語のみ・保留）</a>、<a href="/docs/resources/container_revision.html"><code>takoform_container_revision</code>（英語のみ・保留）</a>、<a href="/docs/resources/container_traffic.html"><code>takoform_container_traffic</code>（英語のみ・保留）</a>、<a href="/docs/resources/container_endpoint.html"><code>takoform_container_endpoint</code>（英語のみ・保留）</a>、<a href="/docs/resources/container_custom_domain.html"><code>takoform_container_custom_domain</code>（英語のみ・保留）</a></li><li>Table / Pull Queue: <a href="/docs/resources/table.html"><code>takoform_table</code>（英語のみ・保留）</a>、<a href="/docs/resources/pull_queue.html"><code>takoform_pull_queue</code>（英語のみ・保留）</a></li><li>Topic: <a href="/docs/resources/topic.html"><code>takoform_topic</code>（英語のみ・保留）</a>、<a href="/docs/resources/topic_subscription.html"><code>takoform_topic_subscription</code>（英語のみ・保留）</a></li><li>Schedule / Vector: <a href="/docs/resources/message_schedule.html"><code>takoform_message_schedule</code>（英語のみ・保留）</a>、<a href="/docs/resources/dense_vector_index.html"><code>takoform_dense_vector_index</code>（英語のみ・保留）</a></li></ul><p>source history は削除せず、履歴・保留ページとしてのみ参照できます。</p><h2 id="その他の-project-surface" tabindex="-1">その他の project surface <a class="header-anchor" href="#その他の-project-surface" aria-label="Permalink to &quot;その他の project surface&quot;">​</a></h2><ul><li><a href="/forms/">Provider 3.0 inventory</a>（英語のみ・履歴） — released Provider projection</li><li><a href="https://github.com/tako0614/takoform-forms/tree/3a395e4d7f9f652a942da52905857fccc41b467e" target="_blank" rel="noreferrer">Current Edge16 publisher roster（英語のみ）</a></li><li><a href="/proposals/">Form Proposals</a>（英語のみ） — Form 設計資料</li><li><a href="/conformance/">Conformance evidence</a>（英語のみ）</li><li><a href="/release/">Release</a>（英語のみ） — publication boundary と履歴</li><li><a href="/docs/glossary.html">Glossary</a>（英語のみ）</li></ul>',19)),s(o)])}const k=r(d,[["render",n]]);export{p as __pageData,k as default};
